import { ChangeEvent, useEffect, useMemo, useRef, useState } from 'react';
import type { Session } from '@supabase/supabase-js';
import { active, areaLabels, blockerLabels, BlockerCategory, canStart, GameRole, gameRoleLabels, Item, Kind, LifeArea, Priority, recommendation, ReplanReason, replanReasonLabels, Status, timing, timingLabels } from './domain';
import { isSupabaseConfigured, supabase } from './supabase';
import { emptyOrganization, normalizeOrganization, Organization, personName, positionsFor } from './org';
import './changes.css';

const today = new Date().toISOString().slice(0, 10);
const make = (title:string, status:Status, extra:Partial<Item> = {}):Item => ({ id:crypto.randomUUID(), title, status, kind:'TASK', priority:'NORMAL', area:'BUSINESS', visibility:'PERSONAL', events:[{id:crypto.randomUUID(),at:new Date().toISOString(),action:'Creado'}], createdAt:new Date().toISOString(), updatedAt:new Date().toISOString(), ...extra });
const seed:Item[]=[
  make('Negociar compra Michelin','ACTIVE',{kind:'PROJECT',gameRole:'QUARTERBACK',role:'Dirección General',priority:'HIGH',dueDate:today,originalDueDate:today,nextAction:'Llamar al proveedor y confirmar bonificación.',progress:60}),
  make('Aprobar campaña WhatsApp','ACTIVE',{gameRole:'REFEREE',role:'Dirección General',priority:'HIGH',dueDate:today,originalDueDate:today,nextAction:'Revisar que las publicaciones cumplan el estándar.'}),
  make('Revisar cartera con Sol','NEXT',{gameRole:'QUARTERBACK',role:'Dirección General',priority:'HIGH',nextAction:'Revisar los diez clientes con mayor cartera vencida.'}),
  make('Diferencias de inventario','BLOCKED',{gameRole:'COACH',role:'Dirección General',priority:'HIGH',person:'Azucena Hernández',blocker:'Falta información para conciliar físico contra sistema.',directManager:'Dirección General',escalatedTo:'Dirección General',escalatedAt:new Date().toISOString(),escalationMethod:'Reunión',escalationMessage:'Se requiere apoyo para definir el criterio de conciliación.',requestedSupport:'Formación y decisión de criterio.',escalationReviewDate:today,reviewDate:today,nextAction:'Revisar conciliación física contra sistema.'}),
  make('Análisis de cartera','WAITING',{person:'Sol Ángel Cruz',dueDate:today,originalDueDate:today,reviewDate:today,priority:'HIGH'}),
  make('Renovar contrato de seguro','INBOX',{area:'DEVELOPMENT'}),
];
const labels:Record<Status,string>={INBOX:'Bandeja',NEXT:'Próximos',ACTIVE:'En curso',BLOCKED:'Bloqueados',SOMEDAY:'Algún día',DONE:'Terminados',CANCELLED:'Cancelados',WAITING:'Esperando'};
const priorities:Priority[]=['CRITICAL','HIGH','NORMAL','LOW'];
const kindLabels:Record<Kind,string>={TASK:'Tarea',PROJECT:'Proyecto',FOLLOW_UP:'Acuerdo / seguimiento',MEETING:'Reunión',DECISION:'Decisión',IDEA:'Idea'};
const roleScreens:Record<string,GameRole>={Quarterback:'QUARTERBACK',Executor:'EXECUTOR',Referee:'REFEREE','DT / Coach':'COACH'};
type ReportFilters={gameRole:string;position:string;flow:string};
const emptyReportFilters:ReportFilters={gameRole:'ALL',position:'ALL',flow:'ALL'};
const normalizeItems=(raw:Item[]):Item[]=>raw.map(item=>{const legacyArea=item.area as unknown as string;const area:LifeArea=legacyArea==='LEARNING'||legacyArea==='HEALTH'||legacyArea==='FAMILY'||legacyArea==='INNER'?'DEVELOPMENT':'BUSINESS';return {...item,area,visibility:item.visibility||'PERSONAL',events:item.events||[],originalDueDate:item.originalDueDate||item.dueDate};});
const dayAfter=(date:string, amount:number)=>{const value=new Date(`${date}T12:00:00`);value.setDate(value.getDate()+amount);return value.toISOString().slice(0,10)};
type CalendarEntry={item:Item;date:string;mode:'COMPROMISO'|'SEGUIMIENTO'|'REUNION'};
const weekEntries=(items:Item[])=>{const end=dayAfter(today,6);return items.flatMap(item=>{const entries:CalendarEntry[]=[];if(item.dueDate)entries.push({item,date:item.dueDate,mode:'COMPROMISO'});if(item.reviewDate&&item.reviewDate!==item.dueDate)entries.push({item,date:item.reviewDate,mode:'SEGUIMIENTO'});if(item.escalationReviewDate&&item.escalationReviewDate!==item.reviewDate)entries.push({item,date:item.escalationReviewDate,mode:'SEGUIMIENTO'});if(item.meetingAt){const date=item.meetingAt.slice(0,10);if(date!==item.dueDate&&date!==item.reviewDate)entries.push({item,date,mode:'REUNION'});}return entries;}).filter(entry=>!['DONE','CANCELLED'].includes(entry.item.status)&&entry.date>=today&&entry.date<=end).sort((a,b)=>a.date.localeCompare(b.date));};

export default function App(){
 const [items,setItems]=useState<Item[]>(()=>normalizeItems(JSON.parse(localStorage.getItem('mi-carril-items')||'null')||seed));
 const backupInput=useRef<HTMLInputElement>(null); const [screen,setScreen]=useState('Comando'); const [capture,setCapture]=useState(false); const [draft,setDraft]=useState(''); const [selected,setSelected]=useState<Item|null>(null); const [message,setMessage]=useState('');
 const [reportFilters,setReportFilters]=useState<ReportFilters>(emptyReportFilters);
 const [organization,setOrganization]=useState<Organization>(()=>normalizeOrganization(JSON.parse(localStorage.getItem('accountability-partner-organization')||'null')||emptyOrganization)); const [organizationSyncError,setOrganizationSyncError]=useState(false);
 const [session,setSession]=useState<Session|null>(null); const [authChecked,setAuthChecked]=useState(!isSupabaseConfigured); const [cloudReady,setCloudReady]=useState(false);
 useEffect(()=>{if(!supabase)return;supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthChecked(true);});const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next));return()=>subscription.unsubscribe();},[]);
 useEffect(()=>{if(!supabase||!session)return;let live=true;supabase.from('items').select('data').order('updated_at',{ascending:false}).then(({data,error})=>{if(!live)return;if(error){setMessage(`No pudimos sincronizar todavía: ${error.message}. Tu copia de este dispositivo está segura.`);return;}const cloudItems=normalizeItems((data||[]).map(row=>row.data as Item));if(cloudItems.length)setItems(cloudItems);setCloudReady(true);});return()=>{live=false;};},[session]);
 useEffect(()=>{if(!supabase||!session)return;let live=true;supabase.from('organization_settings').select('data').eq('owner_id',session.user.id).maybeSingle().then(({data,error})=>{if(!live)return;if(error){setOrganizationSyncError(true);return;}if(data?.data)setOrganization(normalizeOrganization(data.data));setOrganizationSyncError(false);});return()=>{live=false;};},[session]);
 const save=(next:Item[])=>{setItems(next);localStorage.setItem('mi-carril-items',JSON.stringify(next));if(supabase&&session&&cloudReady){const rows=next.map(item=>({id:item.id,owner_id:session.user.id,created_by:session.user.id,assigned_to:null,visibility:item.visibility==='SHARED'?'shared':item.visibility==='COACH_ASSIGNED'?'coach_assigned':'personal',title:item.title,status:item.status,data:item}));supabase.from('items').upsert(rows,{onConflict:'id'}).then(({error})=>{if(error)setMessage('Tu cambio quedó guardado localmente, pero aún no llegó a la nube.');});}};
 const saveOrganization=(next:Organization)=>{setOrganization(next);localStorage.setItem('accountability-partner-organization',JSON.stringify(next));if(supabase&&session){supabase.from('organization_settings').upsert({owner_id:session.user.id,data:next},{onConflict:'owner_id'}).then(({error})=>{if(error){setOrganizationSyncError(true);setMessage('El organigrama quedó guardado en esta computadora. Falta activar su sincronización una sola vez.');}else setOrganizationSyncError(false);});}};
 const update=(id:string,patch:Partial<Item>,action:string,note?:string)=>save(items.map(item=>item.id===id?{...item,...patch,updatedAt:new Date().toISOString(),events:[...item.events,{id:crypto.randomUUID(),at:new Date().toISOString(),action,note}]}:item));
 const start=(item:Item)=>{if(!item.nextAction?.trim())return setMessage('Define qué acción concreta mueve este asunto hacia adelante.');if(!canStart(items,item))return setMessage('Ya tienes 3 asuntos en ejecución. Elige cuál cerrar o bloquear antes de iniciar otro.');update(item.id,{status:'ACTIVE',startedAt:item.startedAt||new Date().toISOString()},'Inició ejecución');};
 const lanes=active(items); const alerts=items.filter(item=>Boolean(item.gameRole)&&(['OVERDUE_UNATTENDED','LATE_REPLAN','OVERDUE_TRACKED'].includes(timing(item))||item.status==='BLOCKED')); const rec=useMemo(()=>recommendation(items),[items]); const reminders=useMemo(()=>weekEntries(items),[items]);
 const openReport=(filters:Partial<ReportFilters>={})=>{setReportFilters({...emptyReportFilters,...filters});setScreen('Reporte');};
 const filtered=items.filter(item=>roleScreens[screen]?item.gameRole===roleScreens[screen]&&!['DONE','CANCELLED'].includes(item.status):screen==='Proyectos'?item.kind==='PROJECT':labels[item.status]===screen);
 const backup=()=>{const blob=new Blob([JSON.stringify({format:'mi-carril-export',schemaVersion:2,appVersion:'0.2.0',exportedAt:new Date().toISOString(),items},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`accountability-partner-respaldo-${today}.json`;link.click();URL.revokeObjectURL(url);setMessage('Respaldo descargado.');};
 const restore=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result));if(data.format!=='mi-carril-export'||!Array.isArray(data.items))throw new Error();if(!confirm(`Restaurar ${data.items.length} asuntos reemplazará la copia de este dispositivo. ¿Ya tienes un respaldo reciente?`))return;save(normalizeItems(data.items));setMessage('Respaldo restaurado correctamente.');}catch{setMessage('El archivo no parece ser un respaldo válido.');}};reader.readAsText(file);event.target.value='';};
 if(!authChecked)return <div className="authpage"><p>Preparando Accountability Partner…</p></div>; if(isSupabaseConfigured&&!session)return <SignIn/>;
 return <div className="shell"><aside><div className="brand">ACCOUNTABILITY<span>PARTNER</span><i>claridad · disciplina · avance</i></div><p className="navlabel">CENTRO DE MANDO</p>{['Comando','Quarterback','Executor','Referee','DT / Coach','Esperando','Bloqueados'].map(x=><button className={screen===x?'nav on':'nav'} onClick={()=>setScreen(x)} key={x}>{x}</button>)}<p className="navlabel">DIRECCIÓN</p>{['Acuerdos','Proyectos','Equipo y estructura','Reporte','Métricas','Terminados','Acceso'].map(x=><button className={screen===x?'nav on':'nav'} onClick={()=>setScreen(x)} key={x}>{x}</button>)}</aside>
 <main><header><div><p className="eyebrow">TU TABLERO DE DIRECCIÓN</p><h1>{screen==='Semana'?'Semana próxima':screen}</h1></div><div className="headeractions">{session&&<span className="userbadge">{session.user.email}</span>}<button className="bell" onClick={()=>setScreen('Semana')}>🔔 <span>AVISOS</span>{reminders.length>0&&<b>{reminders.length}</b>}</button>{session&&<button className="backup" onClick={()=>supabase?.auth.signOut()}>SALIR</button>}<button className="backup" onClick={backup}>RESPALDAR</button><button className="backup" onClick={()=>backupInput.current?.click()}>RESTAURAR</button><input ref={backupInput} className="hidden" type="file" accept="application/json" onChange={restore}/><button className="capture" onClick={()=>setCapture(true)}>+ NUEVO ASUNTO</button></div></header>
 {message&&<div className="toast" onClick={()=>setMessage('')}>{message}</div>}
 {screen==='Comando'&&<><section className="hero"><div><p className="eyebrow">MISIÓN ACTUAL</p><h2>Construir libertad financiera sin sacrificar lo que sostiene tu vida.</h2><p>Una acción que mueve la misión. Un ritmo que puedes mantener.</p></div><div className="heroMark">AP<br/><span>01</span></div></section><section className="focus"><p>SIGUIENTE MOVIMIENTO</p>{rec?<><h2>{rec.title}</h2><span>{areaLabels[rec.area]} · {timingLabels[timing(rec)]}</span><strong>{rec.nextAction||'Define la siguiente acción.'}</strong><button onClick={()=>{start(rec);setScreen(rec.gameRole?gameRoleLabels[rec.gameRole]:'Executor')}}>INICIAR EJECUCIÓN</button></>:<p>No tienes prioridades activas.</p>}</section><CommandCenter items={items} onOpenReport={openReport}/><section><div className="sectionhead"><h2>Radar de atención</h2><span>LO QUE EXIGE DECISIÓN</span></div>{alerts.length?alerts.map(i=><Card key={i.id} item={i} onClick={()=>setSelected(i)}/>):<Empty text="Todo está bajo control por ahora."/>}</section>{items.some(i=>!i.gameRole&&!['DONE','CANCELLED'].includes(i.status))&&<section><div className="sectionhead"><h2>Asuntos sin rol</h2><span>ASÍGNALOS ANTES DE ACTUAR</span></div>{items.filter(i=>!i.gameRole&&!['DONE','CANCELLED'].includes(i.status)).map(i=><Card key={i.id} item={i} onClick={()=>setSelected(i)}/>)}</section>}</>}
 {roleScreens[screen]&&<RoleBoard role={roleScreens[screen]} items={filtered} onClick={setSelected}/>}
 {screen==='Métricas'&&<Metrics items={items}/>} {screen==='Reporte'&&<Report items={items} org={organization} onClick={setSelected} filters={reportFilters} onFiltersChange={setReportFilters}/>} {screen==='Equipo y estructura'&&<OrganizationBoard organization={organization} onSave={saveOrganization} syncError={organizationSyncError}/>} {screen==='Acuerdos'&&<AgreementsBoard items={items} onClick={setSelected}/>} {screen==='Semana'&&<WeekCalendar entries={reminders} onClick={setSelected}/>} {screen==='Acceso'&&<AccessPanel/>}
 {!['Comando','Quarterback','Executor','Referee','DT / Coach','Reporte','Métricas','Equipo y estructura','Acuerdos','Semana','Acceso'].includes(screen)&&<section><p className="intro">{filtered.length} elemento{filtered.length===1?'':'s'}</p>{filtered.length?filtered.map(i=><Card item={i} key={i.id} onClick={()=>setSelected(i)}/>):<Empty text={`${screen} procesada. Nada necesita tu atención aquí.`}/>}</section>}
 </main>{capture&&<Capture draft={draft} setDraft={setDraft} onCancel={()=>setCapture(false)} onSave={(area,gameRole,kind)=>{if(draft.trim()){save([...items,make(draft.trim(),'NEXT',{area,gameRole,kind,kindConfirmed:true})]);setDraft('');setCapture(false);setMessage(`Guardado en ${gameRoleLabels[gameRole]}.`);}}}/>} {selected&&<Detail item={items.find(i=>i.id===selected.id)!} org={organization} onClose={()=>setSelected(null)} onUpdate={update} onStart={start}/>}</div>;
}

function Stat({n,t}:{n:number,t:string}){return <div className="stat"><b>{n}</b><span>{t}</span></div>}
function Empty({text}:{text:string}){return <div className="empty">{text}</div>}
function OrganizationBoard({organization,onSave,syncError}:{organization:Organization;onSave:(next:Organization)=>void;syncError:boolean}){
 const [positionName,setPositionName]=useState('');const [positionArea,setPositionArea]=useState('');const [reportsTo,setReportsTo]=useState('');const [newPerson,setNewPerson]=useState('');const [personId,setPersonId]=useState('');const [positionId,setPositionId]=useState('');const [managerId,setManagerId]=useState('');
 const addPosition=()=>{if(!positionName.trim())return alert('Escribe el nombre del puesto.');onSave({...organization,positions:[...organization.positions,{id:crypto.randomUUID(),name:positionName.trim(),area:positionArea.trim()||undefined,reportsToPositionId:reportsTo||undefined}]});setPositionName('');setPositionArea('');setReportsTo('');};
 const addPerson=()=>{if(!newPerson.trim())return alert('Escribe el nombre completo de la persona.');onSave({...organization,people:[...organization.people,{id:crypto.randomUUID(),name:newPerson.trim(),active:true}]});setNewPerson('');};
 const placePerson=()=>{if(!personId||!positionId)return alert('Selecciona una persona y un puesto.');if(organization.placements.some(placement=>placement.personId===personId&&placement.positionId===positionId))return alert('Esa persona ya está colocada en ese puesto.');onSave({...organization,placements:[...organization.placements,{id:crypto.randomUUID(),personId,positionId,managerPersonId:managerId||undefined}]});setPersonId('');setPositionId('');setManagerId('');};
 const unplace=(id:string)=>onSave({...organization,placements:organization.placements.filter(placement=>placement.id!==id)});
 return <section className="orgboard"><p className="intro">Arma tu estructura como piezas: crea puestos, registra personas y colócalas en la posición que ocupan. Una persona puede tener más de un puesto.</p>{syncError&&<div className="orgwarning"><b>SINCRONIZACIÓN PENDIENTE</b><span>El organigrama está guardado en esta computadora. Para usarlo también en el celular, ejecuta la configuración indicada al final.</span></div>}<div className="orgsteps"><section><p className="eyebrow">1. PUESTOS</p><h2>Crea la estructura</h2><label>Nombre del puesto<input value={positionName} onChange={event=>setPositionName(event.target.value)} placeholder="Ej. Jefe de Operaciones"/></label><label>Área o equipo <input value={positionArea} onChange={event=>setPositionArea(event.target.value)} placeholder="Ej. Operaciones"/></label><label>Este puesto reporta a<select value={reportsTo} onChange={event=>setReportsTo(event.target.value)}><option value="">Sin superior definido</option>{organization.positions.map(position=><option key={position.id} value={position.id}>{position.name}</option>)}</select></label><button onClick={addPosition}>AGREGAR PUESTO</button></section><section><p className="eyebrow">2. PERSONAS</p><h2>Registra a tu equipo</h2><label>Nombre completo<input spellCheck={true} lang="es-MX" value={newPerson} onChange={event=>setNewPerson(event.target.value)} placeholder="Ej. Ricardo Chavira"/></label><button onClick={addPerson}>AGREGAR PERSONA</button><div className="orgpeople">{organization.people.length?organization.people.map(person=><div key={person.id}><b>{person.name}</b><small>{positionsFor(organization,person.id).join(' · ')||'Sin puesto asignado'}</small></div>):<p>Aún no hay personas.</p>}</div></section><section><p className="eyebrow">3. ENSAMBLA</p><h2>Coloca las piezas</h2><label>Persona<select value={personId} onChange={event=>setPersonId(event.target.value)}><option value="">Selecciona persona</option>{organization.people.filter(person=>person.active).map(person=><option key={person.id} value={person.id}>{person.name}</option>)}</select></label><label>Puesto<select value={positionId} onChange={event=>setPositionId(event.target.value)}><option value="">Selecciona puesto</option>{organization.positions.map(position=><option key={position.id} value={position.id}>{position.name}</option>)}</select></label><label>Jefe inmediato (opcional)<select value={managerId} onChange={event=>setManagerId(event.target.value)}><option value="">Según estructura / sin definir</option>{organization.people.filter(person=>person.id!==personId&&person.active).map(person=><option key={person.id} value={person.id}>{person.name}</option>)}</select></label><button onClick={placePerson}>COLOCAR EN EL ORGANIGRAMA</button></section></div><section className="orgmap"><div className="sectionhead"><h2>Tu organigrama</h2><span>{organization.positions.length} PUESTOS · {organization.people.length} PERSONAS</span></div>{organization.positions.length?<div className="orgslots">{organization.positions.map(position=>{const people=organization.placements.filter(placement=>placement.positionId===position.id);const boss=organization.positions.find(parent=>parent.id===position.reportsToPositionId);return <article key={position.id} className="orgslot"><p className="eyebrow">{position.area||'SIN ÁREA'}</p><h3>{position.name}</h3><small>{boss?`Reporta a: ${boss.name}`:'Puesto raíz / superior por definir'}</small><div>{people.length?people.map(placement=><span className="personchip" key={placement.id}>{personName(organization,placement.personId)}{placement.managerPersonId&&<i> · jefe: {personName(organization,placement.managerPersonId)}</i>}<button title="Quitar de este puesto" onClick={()=>unplace(placement.id)}>×</button></span>):<em>Disponible: aún sin persona.</em>}</div></article>;})}</div>:<Empty text="Comienza agregando el primer puesto; aparecerá aquí como una pieza de tu organigrama."/>}</section></section>;
}
function CommandCenter({items,onOpenReport}:{items:Item[];onOpenReport:(filters?:Partial<ReportFilters>)=>void}){
 const open=items.filter(item=>!['DONE','CANCELLED','SOMEDAY'].includes(item.status));
 const roles:GameRole[]=['QUARTERBACK','EXECUTOR','REFEREE','COACH'];
 const flows:{status:Status;label:string}[]=[{status:'NEXT',label:'Por iniciar'},{status:'ACTIVE',label:'En ejecución'},{status:'WAITING',label:'Esperando'},{status:'BLOCKED',label:'Bloqueados'}];
 const count=(role?:GameRole,status?:Status)=>open.filter(item=>(!role||item.gameRole===role)&&(!status||item.status===status)).length;
 return <section className="commandcenter"><div className="sectionhead"><h2>Control de jugadas</h2><button className="linkbutton" onClick={()=>onOpenReport()}>VER REPORTE COMPLETO →</button></div><p className="intro">Toca cualquier cifra para abrir las actividades exactas que la componen.</p><div className="commandtotals"><button className="commandtile total" onClick={()=>onOpenReport()}><b>{open.length}</b><span>Actividades abiertas</span></button>{roles.map(role=><button className="commandtile" key={role} onClick={()=>onOpenReport({gameRole:role})}><b>{count(role)}</b><span>{gameRoleLabels[role]}</span></button>)}</div><div className="commandflow"><div><p className="eyebrow">ESTADO DEL FLUJO</p>{flows.map(flow=><button key={flow.status} onClick={()=>onOpenReport({flow:flow.status})}><span>{flow.label}</span><b>{count(undefined,flow.status)}</b></button>)}</div><div className="matrix"><p className="eyebrow">CRUCE: TU PAPEL × ESTADO</p><div className="matrixscroll"><table><thead><tr><th>Rol</th>{flows.map(flow=><th key={flow.status}>{flow.label}</th>)}</tr></thead><tbody>{roles.map(role=><tr key={role}><th>{gameRoleLabels[role]}</th>{flows.map(flow=><td key={flow.status}><button onClick={()=>onOpenReport({gameRole:role,flow:flow.status})}>{count(role,flow.status)}</button></td>)}</tr>)}</tbody></table></div></div></div></section>;
}
function Metrics({items}:{items:Item[]}){const all=items.filter(i=>!['INBOX','SOMEDAY','CANCELLED'].includes(i.status));const onTime=all.filter(i=>timing(i)==='ON_TIME').length;return <><div className="grid four"><Stat n={items.filter(i=>i.status==='DONE').length} t="Terminados"/><Stat n={onTime} t="En tiempo"/><Stat n={all.filter(i=>timing(i)==='RISK_INFORMED').length} t="Riesgo informado"/><Stat n={all.filter(i=>timing(i)==='OVERDUE_UNATTENDED').length} t="Vencidos sin atención"/></div><section className="metricsnote"><h2>Lectura de compromiso</h2><p>Amarillo: se avisó antes del vencimiento. Naranja: se reaccionó tarde. Rojo: venció sin atención registrada.</p></section></>}
function Report({items,org,onClick,filters,onFiltersChange}:{items:Item[];org:Organization;onClick:(item:Item)=>void;filters:ReportFilters;onFiltersChange:(filters:ReportFilters)=>void}){
 const [view,setView]=useState<'ROLE'|'FLOW'>('ROLE'); const [personFilter,setPersonFilter]=useState('ALL'); const {gameRole,position,flow}=filters;
 const positions=Array.from(new Set(items.map(item=>item.role).filter(Boolean))) as string[];
 const reportItems=useMemo(()=>items.filter(item=>{if(['INBOX','SOMEDAY','CANCELLED'].includes(item.status))return false;const personMatches=personFilter==='ALL'||item.personId===personFilter||(item.participantIds||[]).includes(personFilter);return personMatches&&(gameRole==='ALL'||item.gameRole===gameRole)&&(position==='ALL'||item.role===position)&&(flow==='ALL'||item.status===flow);}).sort((a,b)=>{const left=view==='ROLE'?(a.gameRole||'ZZ'):(labels[a.status]);const right=view==='ROLE'?(b.gameRole||'ZZ'):(labels[b.status]);return left.localeCompare(right)||a.title.localeCompare(b.title);}),[items,gameRole,position,flow,personFilter,view]);
 const lastAdvance=(item:Item)=>[...item.events].reverse().find(event=>event.action==='Avance registrado')?.at;
 const csv=()=>{const quote=(value:string|undefined)=>`"${(value||'').replaceAll('"','""')}"`;const header=['Actividad','Rol en la jugada','Actúas como','Estado del flujo','Semáforo','Fecha entrega actual','Fecha original','Inicio de ejecución','Próximo seguimiento','Último avance','Siguiente acción'];const rows=reportItems.map(item=>[item.title,item.gameRole?gameRoleLabels[item.gameRole]:'Sin rol',item.role||'',labels[item.status],timingLabels[timing(item)],item.dueDate||'',item.originalDueDate||'',item.startedAt?.slice(0,10)||'',item.reviewDate||'',lastAdvance(item)?.slice(0,10)||'',item.nextAction||'']);const content='\ufeff'+[header,...rows].map(row=>row.map(value=>quote(value)).join(',')).join('\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`reporte-accountability-${today}.csv`;link.click();URL.revokeObjectURL(url);};
 return <section className="report"><p className="intro">Lee tus compromisos por la responsabilidad que juegas, la persona involucrada o el estado en que se encuentra el flujo.</p><div className="reporttabs"><button className={view==='ROLE'?'selected':''} onClick={()=>setView('ROLE')}>VER POR ROL EN LA JUGADA</button><button className={view==='FLOW'?'selected':''} onClick={()=>setView('FLOW')}>VER POR FLUJO</button><button className="export" onClick={csv}>DESCARGAR EXCEL (.CSV)</button></div><div className="reportfilters"><label>Jugador / involucrado<select value={personFilter} onChange={e=>setPersonFilter(e.target.value)}><option value="ALL">Todas las personas</option>{org.people.filter(person=>person.active).map(person=><option key={person.id} value={person.id}>{person.name}</option>)}</select></label><label>Rol en la jugada<select value={gameRole} onChange={e=>onFiltersChange({...filters,gameRole:e.target.value})}><option value="ALL">Todos los roles</option>{Object.entries(gameRoleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Actúas como<select value={position} onChange={e=>onFiltersChange({...filters,position:e.target.value})}><option value="ALL">Todas las posiciones</option>{positions.map(value=><option key={value}>{value}</option>)}</select></label><label>Estado del flujo<select value={flow} onChange={e=>onFiltersChange({...filters,flow:e.target.value})}><option value="ALL">Todos los estados</option>{Object.entries(labels).filter(([key])=>!['INBOX','SOMEDAY','CANCELLED'].includes(key)).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label></div><p className="reportcount">{reportItems.length} actividad{reportItems.length===1?'':'es'} en el reporte</p><div className="reporttablewrap"><table><thead><tr><th>Actividad</th><th>Responsable / involucrados</th><th>Rol / posición</th><th>Flujo</th><th>Semáforo</th><th>Fechas</th><th>Seguimiento</th></tr></thead><tbody>{reportItems.map(item=><tr key={item.id} onClick={()=>onClick(item)}><td><b>{item.title}</b><small>{item.nextAction||'Sin siguiente acción'}</small></td><td><b>{personName(org,item.personId,item.person)}</b><small>{(item.participantIds||[]).map(id=>personName(org,id)).join(', ')||item.participants||'Sin involucrados registrados'}</small></td><td><b>{item.gameRole?gameRoleLabels[item.gameRole]:'Sin rol'}</b><small>{item.role||'Sin posición organizacional'}</small></td><td>{labels[item.status]}</td><td><span className={`timing timing-${timing(item).toLowerCase()}`}>{timingLabels[timing(item)]}</span></td><td><small>Actual: {item.dueDate||'—'}</small><small>Original: {item.originalDueDate||'—'}</small><small>Inicio: {item.startedAt?.slice(0,10)||'—'}</small></td><td><small>Próximo: {item.reviewDate||'—'}</small><small>Avance: {lastAdvance(item)?.slice(0,10)||'—'}</small></td></tr>)}</tbody></table>{!reportItems.length&&<Empty text="No hay actividades con estos filtros."/>}</div></section>;
}
function RoleBoard({role,items,onClick}:{role:GameRole;items:Item[];onClick:(item:Item)=>void}){const descriptions:Record<GameRole,string>={QUARTERBACK:'Eres dueño del resultado: convocas, coordinas, detectas bloqueos y aseguras el cierre.',EXECUTOR:'La entrega depende totalmente de ti: nadie la hará por ti.',REFEREE:'Revisas el resultado contra el estándar; validas, devuelves observaciones o rechazas.',COACH:'El asunto ya escaló. Formas criterio, desbloqueas capacidad o tomas una decisión de dirección.'};return <section><p className="intro"><b>{gameRoleLabels[role]}:</b> {descriptions[role]}</p>{items.length?items.map(item=><Card key={item.id} item={item} onClick={()=>onClick(item)}/>):<Empty text={`No hay asuntos asignados como ${gameRoleLabels[role]}.`}/>}</section>}
function AgreementsBoard({items,onClick}:{items:Item[];onClick:(item:Item)=>void}){const open=items.filter(i=>!['DONE','CANCELLED','INBOX','SOMEDAY'].includes(i.status));const groups:[GameRole,string][]=[['QUARTERBACK','QUARTERBACKS'],['EXECUTOR','EJECUTORES'],['REFEREE','REFEREES'],['COACH','DT / COACH']];return <section><p className="intro">Cada rol tiene una responsabilidad distinta: consolidar, ejecutar, validar o desarrollar capacidad.</p><div className="agreementgrid">{groups.map(([role,title])=>{const group=open.filter(i=>i.gameRole===role);return <div className="agreementlane" key={role}><span>{title}</span>{group.length?group.map(i=><Card item={i} key={i.id} onClick={()=>onClick(i)}/>):<Empty text="Sin asuntos en este rol."/>}</div>})}</div></section>}
function WeekCalendar({entries,onClick}:{entries:CalendarEntry[];onClick:(item:Item)=>void}){const dates=Array.from({length:7},(_,i)=>dayAfter(today,i));return <section><p className="intro">Compromisos, reuniones y revisiones de los próximos siete días.</p><div className="weekgrid">{dates.map(date=>{const dayEntries=entries.filter(entry=>entry.date===date);const label=new Date(`${date}T12:00:00`).toLocaleDateString('es-MX',{weekday:'short',day:'numeric',month:'short'});return <div className="daycolumn" key={date}><span>{label}</span>{dayEntries.length?dayEntries.map(entry=><button className={`calendarentry ${entry.mode.toLowerCase()}`} key={`${entry.item.id}-${entry.mode}`} onClick={()=>onClick(entry.item)}><small>{entry.mode==='COMPROMISO'?'COMPROMISO':entry.mode==='REUNION'?'REUNIÓN':'SEGUIMIENTO'}</small><b>{entry.item.title}</b>{entry.item.person&&<em>Responsable: {entry.item.person}</em>}</button>):<p>Sin compromisos.</p>}</div>})}</div></section>}
function Card({item,onClick}:{item:Item;onClick:()=>void}){const state=timing(item);return <button className={`card timing-${state.toLowerCase()}`} onClick={onClick}><div><small>{item.gameRole?gameRoleLabels[item.gameRole]:'Sin rol'} · {item.priority}</small><h3>{item.title}</h3>{item.nextAction&&<p>{item.nextAction}</p>}</div><div className="meta"><span className={`timing timing-${state.toLowerCase()}`}>{timingLabels[state]}</span>{item.dueDate&&<span>{item.dueDate===today?'Vence hoy':`Entrega ${item.dueDate}`}</span>}</div></button>}
function Capture({draft,setDraft,onCancel,onSave}:{draft:string;setDraft:(x:string)=>void;onCancel:()=>void;onSave:(area:LifeArea,role:GameRole,kind:Kind)=>void}){const [area,setArea]=useState<LifeArea>('BUSINESS');const [role,setRole]=useState<GameRole|''>('');const [kind,setKind]=useState<Kind|''>('');const create=()=>{if(!draft.trim()||!role||!kind){alert('Para crear un asunto debes indicar su tipo y tu rol en la jugada.');return;}onSave(area,role,kind);};return <div className="overlay"><div className="modal capturemodal"><button className="close" onClick={onCancel}>×</button><p className="eyebrow">NUEVO ASUNTO</p><h2>¿Qué necesita atención?</h2><textarea autoFocus spellCheck={true} lang="es-MX" value={draft} onChange={e=>setDraft(e.target.value)} placeholder="Ej. Comprar agua para el almacén."/><div className="formgrid"><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value as Kind)}><option value="">Selecciona tipo</option>{Object.entries(kindLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Rol en la jugada<select value={role} onChange={e=>setRole(e.target.value as GameRole)}><option value="">Selecciona rol</option>{Object.entries(gameRoleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label></div><label>Enfoque del asunto<select value={area} onChange={e=>setArea(e.target.value as LifeArea)}>{Object.entries(areaLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><button className="primary" onClick={create}>CREAR ASUNTO</button></div></div>}
function SignIn(){const [email,setEmail]=useState('');const [sent,setSent]=useState(false);const [error,setError]=useState('');const send=async()=>{if(!supabase||!email.trim())return;const {error:loginError}=await supabase.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:window.location.href}});if(loginError)setError(loginError.message);else setSent(true);};return <div className="authpage"><div className="authcard"><div className="brand dark">ACCOUNTABILITY<span>PARTNER</span><i>claridad · disciplina · avance</i></div><h1>Tu centro de dirección</h1>{sent?<p>Revisa tu correo y abre el enlace de acceso.</p>:<><p>Entra para conservar tu dirección y trabajar desde cualquier dispositivo.</p><label>Tu correo<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="tu@correo.com"/></label>{error&&<p className="autherror">{error}</p>}<button className="primary" onClick={send}>ENVIAR ENLACE DE ACCESO</button></>}</div></div>}
function AccessPanel(){return <section className="accesspanel"><p className="eyebrow">PRIVACIDAD Y ACOMPAÑAMIENTO</p><h2>Tu vida completa no es el tablero de nadie.</h2><p>El coach verá únicamente los asuntos que decidas compartir.</p><div className="accessgrid"><div><b>ENFOQUES ACTUALES</b><strong>Operación y crecimiento del negocio</strong><strong>Formación y desarrollo profesional</strong></div><div className="locked"><b>PRIVACIDAD POR ASUNTO</b><strong>Solo tú decides cuáles asuntos compartir.</strong><strong>La estructura completa de permisos se construirá con el módulo de Equipo.</strong></div></div></section>}
function PreviewField({label,value}:{label:string;value:string}){return <div className="previewfield"><b>{label}</b><span>{value}</span></div>}
function SharePreview({item,org,onClose}:{item:Item;org:Organization;onClose:()=>void}){
 const responsible=personName(org,item.personId,item.person); const people=(item.participantIds||[]).map(id=>personName(org,id)).join(', ')||item.participants||'—';
 const summary=`ACCOUNTABILITY PARTNER\n${item.title}\n${labels[item.status]} · ${timingLabels[timing(item)]}\nRol: ${item.gameRole?gameRoleLabels[item.gameRole]:'Sin rol'}\nResponsable: ${responsible}\nEntrega: ${item.dueDate||'Sin fecha'}\nPróximo movimiento: ${item.nextAction||'Sin definir'}\nCondición para avanzar: ${item.blocker||'Sin condición registrada'}`;
 const copy=async()=>{try{await navigator.clipboard.writeText(summary);alert('Resumen copiado.');}catch{alert('No fue posible copiar automáticamente. Puedes seleccionar el texto de esta ficha.');}};
 return <div className="shareoverlay"><article className="sharecard"><button className="close" onClick={onClose}>×</button><p className="eyebrow">ACCOUNTABILITY PARTNER · FICHA PARA COMPARTIR</p><p className={`sharestatus timing-${timing(item).toLowerCase()}`}>{labels[item.status]} · {timingLabels[timing(item)]}</p><h2>{item.title}</h2><div className="sharefacts"><div><b>ROL EN LA JUGADA</b><span>{item.gameRole?gameRoleLabels[item.gameRole]:'Sin rol'}</span></div><div><b>RESPONSABLE</b><span>{responsible}</span></div><div><b>ENTREGA</b><span>{item.dueDate||'Sin fecha'}</span></div><div><b>INVOLUCRADOS</b><span>{people}</span></div></div><section><b>PRÓXIMO MOVIMIENTO</b><p>{item.nextAction||'Aún no está definido.'}</p></section><section><b>CONDICIÓN PARA AVANZAR</b><p>{item.blocker||'No se ha identificado una condición.'}</p></section><footer><span>Generado {new Date().toLocaleDateString('es-MX')}</span><button onClick={copy}>COPIAR RESUMEN</button></footer><p className="sharehint">Para compartir la imagen: usa <b>Windows + Shift + S</b> y captura esta ficha.</p></article></div>;
}

function Detail({item,org,onClose,onUpdate,onStart}:{item:Item;org:Organization;onClose:()=>void;onUpdate:(id:string,p:Partial<Item>,a:string,n?:string)=>void;onStart:(i:Item)=>void}){
 const [draft,setDraft]=useState<Item>(item); const [note,setNote]=useState(''); const [completionNote,setCompletionNote]=useState(''); const [showComplete,setShowComplete]=useState(false); const [showBlock,setShowBlock]=useState(item.status==='BLOCKED'); const [showReplan,setShowReplan]=useState(false); const [showSharePreview,setShowSharePreview]=useState(false); const [editing,setEditing]=useState(false);
 useEffect(()=>setDraft(item),[item]);
 const set=(patch:Partial<Item>)=>setDraft(value=>({...value,...patch}));
 const saveDetails=()=>{if(!draft.gameRole||!draft.kindConfirmed){alert('Para guardar debes seleccionar el tipo y el rol en la jugada.');return;}const patch:Partial<Item>={...draft};delete patch.id;delete patch.events;delete patch.createdAt;delete patch.updatedAt;if(draft.dueDate&&!item.originalDueDate)patch.originalDueDate=draft.dueDate;onUpdate(item.id,patch,'Detalles del asunto actualizados');setEditing(false);};
 const formalBlock=()=>{if(!draft.blocker?.trim()||!draft.escalatedTo?.trim()||!draft.escalatedAt||!draft.escalationMethod?.trim()||!draft.escalationMessage?.trim()||!draft.requestedSupport?.trim()||!draft.escalationReviewDate){alert('Para bloquear formalmente falta causa, superior informado, fecha, medio, mensaje, apoyo solicitado y fecha de revisión.');return;}onUpdate(item.id,{...draft,status:'BLOCKED'},'Bloqueo formal escalado',note||draft.blocker);setShowBlock(false);};
 const requestReplan=()=>{if(!draft.requestedDueDate||!draft.replanReason||!draft.replanNote?.trim()||!draft.replanNotifiedTo?.trim()||!draft.replanMethod?.trim()){alert('Para solicitar cambio de fecha falta nueva fecha, razón, explicación y a quién/por qué medio avisaste.');return;}onUpdate(item.id,{requestedDueDate:draft.requestedDueDate,replanReason:draft.replanReason,replanNote:draft.replanNote,replanNotifiedTo:draft.replanNotifiedTo,replanMethod:draft.replanMethod,replanImpact:draft.replanImpact,replanRequestedAt:new Date().toISOString(),replanStatus:'PENDING'},'Solicitud de replaneación enviada',draft.replanNote);setShowReplan(false);};
 const approveReplan=()=>{if(!item.requestedDueDate)return;onUpdate(item.id,{dueDate:item.requestedDueDate,replanStatus:'APPROVED'},'Nueva fecha aprobada',`Compromiso actualizado a ${item.requestedDueDate}.`);};
 const complete=()=>{if(!completionNote.trim())return alert('Para concluir necesitas registrar un comentario de cierre: resultado, evidencia o razón.');onUpdate(item.id,{status:'DONE'},'Resultado terminado',completionNote);setCompletionNote('');setShowComplete(false);};
 const relevant=item.events.filter(event=>!['Área actualizada','Privacidad actualizada','Tipo actualizado','Personas involucradas actualizadas','Responsable actualizado','Prioridad actualizada','Siguiente acción actualizada'].includes(event.action));
 const printItem=()=>{const printWindow=window.open('','_blank');if(!printWindow){alert('El navegador bloqueó la ventana de impresión. Permite ventanas emergentes e inténtalo otra vez.');return;}const escape=(value:string)=>value.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]||char));const fields:[string,string][]=[['Rol en la jugada',item.gameRole?gameRoleLabels[item.gameRole]:'Pendiente de definir'],['Tipo',item.kindConfirmed?kindLabels[item.kind]:'Pendiente de definir'],['Enfoque',areaLabels[item.area]],['Actúo como',item.role||'Sin posición organizacional'],['Responsable de la entrega',personName(org,item.personId,item.person)],['Participantes',(item.participantIds||[]).map(id=>personName(org,id)).join(', ')||item.participants||'No registrados'],['Fecha de entrega comprometida',item.dueDate||'Sin fecha'],['Fecha original',item.originalDueDate||'Sin fecha'],['Fecha para pedir avance',item.reviewDate||'Sin fecha'],['Próxima reunión',item.meetingAt?new Date(item.meetingAt).toLocaleString('es-MX'):'No programada']];const history=relevant.length?[...relevant].reverse().map(event=>`<li><b>${escape(new Date(event.at).toLocaleString('es-MX'))}</b><br>${escape(event.action)}${event.note?`: ${escape(event.note)}`:''}</li>`).join(''):'<li>Aún no hay eventos relevantes.</li>';printWindow.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${escape(item.title)}</title><style>@page{margin:16mm}body{font-family:Arial,sans-serif;color:#132333;line-height:1.4}header{border-top:5px solid #159bff;padding-top:18px;margin-bottom:24px}.brand{color:#087bd3;font-size:11px;font-weight:800;letter-spacing:2px}.status{color:#486579;font-size:12px;margin:8px 0}h1{font-size:27px;margin:0 0 8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field{border:1px solid #b7c8d4;padding:10px}.field b,.section b{display:block;color:#43667d;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:4px}.section{background:#edf4f8;border-left:4px solid #159bff;padding:12px 14px;margin-top:13px}.section p{margin:0}.history{margin-top:25px}.history li{margin:0 0 10px;padding-left:4px}.history b{color:#1f5274}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><header><div class="brand">ACCOUNTABILITY PARTNER · FICHA DE ACTIVIDAD</div><div class="status">${escape(labels[item.status])} · ${escape(timingLabels[timing(item)])}</div><h1>${escape(item.title)}</h1></header><div class="grid">${fields.map(([label,value])=>`<div class="field"><b>${escape(label)}</b>${escape(value)}</div>`).join('')}</div><div class="section"><b>Próximo movimiento</b><p>${escape(item.nextAction||'Aún no está definido.')}</p></div><div class="section"><b>Condición para avanzar</b><p>${escape(item.blocker||'No se ha identificado una condición.')}</p></div><div class="history"><b>Historial relevante</b><ul>${history}</ul></div></body></html>`);printWindow.document.close();window.setTimeout(()=>{printWindow.focus();printWindow.print();},250);};
 if(!editing)return <div className="overlay"><div className="modal detailmodal preview"><button className="close" onClick={onClose}>×</button><small>{labels[item.status]} · {timingLabels[timing(item)]}</small><h2>{item.title}</h2><div className="previewgrid"><PreviewField label="Rol en la jugada" value={item.gameRole?gameRoleLabels[item.gameRole]:'Pendiente de definir'}/><PreviewField label="Tipo" value={item.kindConfirmed?kindLabels[item.kind]:'Pendiente de definir'}/><PreviewField label="Enfoque" value={areaLabels[item.area]}/><PreviewField label="Actúo como" value={item.role||'Sin posición organizacional'}/><PreviewField label="Responsable de la entrega" value={personName(org,item.personId,item.person)}/><PreviewField label="Participantes" value={(item.participantIds||[]).map(id=>personName(org,id)).join(', ')||item.participants||'No registrados'}/><PreviewField label="Fecha de entrega comprometida" value={item.dueDate||'Sin fecha'}/><PreviewField label="Fecha original" value={item.originalDueDate||'Sin fecha'}/><PreviewField label="Fecha para pedir avance" value={item.reviewDate||'Sin fecha'}/><PreviewField label="Próxima reunión" value={item.meetingAt?new Date(item.meetingAt).toLocaleString('es-MX'):'No programada'}/></div><section className="previewsection"><b>PRÓXIMO MOVIMIENTO</b><p>{item.nextAction||'Aún no está definido.'}</p></section><section className="previewsection"><b>CONDICIÓN PARA AVANZAR</b><p>{item.blocker||'No se ha identificado una condición.'}</p></section><div className="previewactions"><button className="primary" onClick={()=>setEditing(true)}>EDITAR ASUNTO</button><button onClick={()=>setShowSharePreview(true)}>VISTA PARA COMPARTIR</button><button onClick={printItem}>GUARDAR / COMPARTIR PDF</button></div><h3>Historial relevante</h3><div className="timeline">{relevant.length?[...relevant].reverse().map(event=><p key={event.id}><b>{new Date(event.at).toLocaleString('es-MX')}</b>{event.action}{event.note&&`: ${event.note}`}</p>):<p>Aún no hay eventos relevantes.</p>}</div>{showSharePreview&&<SharePreview item={item} org={org} onClose={()=>setShowSharePreview(false)}/>}</div></div>;
 return <div className="overlay"><div className="modal detailmodal"><button className="close" onClick={onClose}>×</button><small>{labels[item.status]} · {timingLabels[timing(item)]}</small><h2>{item.title}</h2>
 <div className="formgrid"><label>Rol en la jugada<select value={draft.gameRole||''} onChange={e=>set({gameRole:(e.target.value||undefined) as GameRole|undefined})}><option value="">Selecciona rol</option>{Object.entries(gameRoleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Tipo<select value={draft.kindConfirmed?draft.kind:''} onChange={e=>set({kind:e.target.value as Kind,kindConfirmed:true})}><option value="">Selecciona tipo</option>{Object.entries(kindLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Enfoque del asunto<select value={draft.area} onChange={e=>set({area:e.target.value as LifeArea})}>{Object.entries(areaLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Prioridad<select value={draft.priority} onChange={e=>set({priority:e.target.value as Priority})}>{priorities.map(p=><option key={p}>{p}</option>)}</select></label></div>
 {org.people.length?<><label>Responsable de la entrega<select value={draft.personId||''} onChange={event=>{const id=event.target.value;set({personId:id||undefined,person:id?personName(org,id):undefined});}}><option value="">Sin asignar</option>{org.people.filter(person=>person.active).map(person=><option key={person.id} value={person.id}>{person.name}</option>)}</select></label><label>Participantes<select multiple value={draft.participantIds||[]} onChange={event=>{const ids=Array.from(event.target.selectedOptions).map(option=>option.value);set({participantIds:ids,participants:ids.map(id=>personName(org,id)).join(', ')});}}>{org.people.filter(person=>person.active).map(person=><option key={person.id} value={person.id}>{person.name}</option>)}</select><small className="fieldhelp">Usa Ctrl para seleccionar más de una persona.</small></label></>:<><label>Responsable de la entrega<input value={draft.person||''} onChange={e=>set({person:e.target.value})} placeholder="Primero registra a tu equipo para elegirlo aquí"/></label><label>Participantes<input value={draft.participants||''} onChange={e=>set({participants:e.target.value})} placeholder="Primero registra a tu equipo para elegirlo aquí"/></label></>}<label>Actúo como<input value={draft.role||''} onChange={e=>set({role:e.target.value})} placeholder="Ej. Dirección General, Comprador o Vendedor"/></label><div className="formgrid"><label>Fecha de entrega comprometida<input type="date" value={draft.dueDate||''} onChange={e=>set({dueDate:e.target.value||undefined})}/></label><label>Fecha para pedir avance<input type="date" value={draft.reviewDate||''} onChange={e=>set({reviewDate:e.target.value||undefined})}/></label><label>Próxima reunión (solo si hay cita)<input type="datetime-local" value={draft.meetingAt||''} onChange={e=>set({meetingAt:e.target.value||undefined})}/></label></div>
 <label>Próximo movimiento<input value={draft.nextAction||''} onChange={e=>set({nextAction:e.target.value})} placeholder="La primera acción concreta que debe ocurrir"/></label><label>Condición para avanzar<input value={draft.blocker||''} onChange={e=>set({blocker:e.target.value})} placeholder="Qué falta o debe ocurrir para seguir"/></label><div className="actions"><button onClick={()=>setEditing(false)}>CANCELAR EDICIÓN</button><button className="primary" onClick={saveDetails}>GUARDAR CAMBIOS</button></div>
 {item.status==='INBOX'&&<div className="actions"><button onClick={()=>onUpdate(item.id,{status:'NEXT'},'Procesado y enviado a Próximos')}>DEFINIR DESPUÉS</button><button onClick={()=>onUpdate(item.id,{status:'SOMEDAY'},'Guardado como idea')}>ES IDEA</button></div>}
 {['NEXT','BLOCKED'].includes(item.status)&&<button className="primary" onClick={()=>onStart({...item,nextAction:draft.nextAction})}>{item.status==='BLOCKED'?'DESBLOQUEAR E INICIAR':'INICIAR EJECUCIÓN'}</button>}
 {item.status==='DONE'&&<button className="primary" onClick={()=>onUpdate(item.id,{status:'NEXT'},'Reactivado y enviado a Próximos')}>REACTIVAR</button>}
 {!['DONE','CANCELLED','INBOX','SOMEDAY'].includes(item.status)&&<div className="actions"><button onClick={()=>setShowReplan(!showReplan)}>SOLICITAR CAMBIO DE FECHA</button>{item.replanStatus==='PENDING'&&<button onClick={approveReplan}>APROBAR NUEVA FECHA</button>}</div>}
 {showReplan&&<section className="subform"><h3>Solicitud de replaneación</h3><p>La fecha original no se borra. Esta solicitud queda registrada y debe ser aprobada.</p><label>Nueva fecha solicitada<input type="date" value={draft.requestedDueDate||''} onChange={e=>set({requestedDueDate:e.target.value})}/></label><label>Razón<select value={draft.replanReason||''} onChange={e=>set({replanReason:e.target.value as ReplanReason})}><option value="">Elige la razón</option>{Object.entries(replanReasonLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Explicación<input value={draft.replanNote||''} onChange={e=>set({replanNote:e.target.value})} placeholder="Qué ocurrió y qué harás para cumplir"/></label><label>Superior informado<input value={draft.replanNotifiedTo||''} onChange={e=>set({replanNotifiedTo:e.target.value})}/></label><label>Medio de aviso<input value={draft.replanMethod||''} onChange={e=>set({replanMethod:e.target.value})} placeholder="WhatsApp, correo, reunión…"/></label><label>Impacto en otras áreas<input value={draft.replanImpact||''} onChange={e=>set({replanImpact:e.target.value})}/></label><button onClick={requestReplan}>REGISTRAR SOLICITUD</button></section>}
 {!['DONE','CANCELLED','INBOX','SOMEDAY'].includes(item.status)&&<div className="actions"><button className="completebutton" onClick={()=>setShowComplete(!showComplete)}>CONCLUIR TAREA</button></div>}
 {showComplete&&<section className="subform completion"><h3>Concluir tarea</h3><p>Registra qué se entregó, dónde queda la evidencia o por qué puede darse por cerrada. Este comentario formará parte del historial.</p><label>Comentario de cierre / resultado<textarea spellCheck={true} lang="es-MX" value={completionNote} onChange={event=>setCompletionNote(event.target.value)} placeholder="Ej. Se entregó la factura al cliente; evidencia: correo enviado el 26 de agosto."/></label><button onClick={complete}>CONFIRMAR CONCLUSIÓN</button></section>}
 {item.status==='ACTIVE'&&<><div className="actions"><button onClick={()=>setShowBlock(!showBlock)}>DECLARAR BLOQUEO</button></div><label>Nota de avance o acuerdo<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Qué pasó, qué sigue y quién queda responsable"/></label><button onClick={()=>{if(!note.trim())return alert('Escribe una nota de avance antes de registrarla.');onUpdate(item.id,{progress:item.kind==='PROJECT'?Math.min(100,(item.progress||0)+10):item.progress},'Avance registrado',note);setNote('');}}>REGISTRAR AVANCE</button></>}
 {showBlock&&<section className="subform"><h3>Bloqueo formal</h3><p>Un bloqueo exige causa, escalamiento y fecha de seguimiento. Así nadie puede dejar un asunto detenido sin avisar.</p><label>Causa del bloqueo<select value={draft.blockerCategory||''} onChange={e=>set({blockerCategory:e.target.value as BlockerCategory})}><option value="">Elige la causa</option>{Object.entries(blockerLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Qué impide avanzar<input value={draft.blocker||''} onChange={e=>set({blocker:e.target.value})}/></label><label>Jefe inmediato / superior<input value={draft.directManager||''} onChange={e=>set({directManager:e.target.value})}/></label><label>A quién se escaló<input value={draft.escalatedTo||''} onChange={e=>set({escalatedTo:e.target.value})}/></label><label>Fecha y hora de aviso<input type="datetime-local" value={draft.escalatedAt?.slice(0,16)||''} onChange={e=>set({escalatedAt:e.target.value?new Date(e.target.value).toISOString():undefined})}/></label><label>Medio de aviso<input value={draft.escalationMethod||''} onChange={e=>set({escalationMethod:e.target.value})} placeholder="WhatsApp, llamada, correo, reunión…"/></label><label>Mensaje / resumen informado<textarea value={draft.escalationMessage||''} onChange={e=>set({escalationMessage:e.target.value})}/></label><label>Apoyo solicitado<input value={draft.requestedSupport||''} onChange={e=>set({requestedSupport:e.target.value})} placeholder="Decisión, presupuesto, apoyo, formación…"/></label><label>Fecha para revisar respuesta<input type="date" value={draft.escalationReviewDate||''} onChange={e=>set({escalationReviewDate:e.target.value})}/></label><button onClick={formalBlock}>REGISTRAR BLOQUEO FORMAL</button></section>}
 {item.kind==='PROJECT'&&<label>Progreso<input type="number" min="0" max="100" value={draft.progress??0} onChange={e=>set({progress:Number(e.target.value)})}/></label>}
 <h3>Historial relevante</h3><div className="timeline">{relevant.length?[...relevant].reverse().map(event=><p key={event.id}><b>{new Date(event.at).toLocaleString('es-MX')}</b>{event.action}{event.note&&`: ${event.note}`}</p>):<p>Aún no hay eventos relevantes.</p>}</div></div></div>;
}
